  clientId: string;
  redirectUri: string;
  codeChallenge: string;
  scopes: string[];
  resource: string;
  expiresAt: number;
}
interface TokenRecord {
  clientId: string;
  scopes: string[];
  resource: string;
  expiresAt: number;
  subject: string;
  supersededAt?: number;
