import assert from "node:assert/strict";
import { spawn } from "node:child_process";
import { createServer } from "node:http";
import { connect } from "node:net";
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

const repo = "C:\\Users\\Lauri\\AppData\\Local\\ChatGPTMcpClean";
const temp = mkdtempSync(join(tmpdir(), "mcp-front-client-error-"));
const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function listen(server) {
  await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
  return server.address().port;
}

async function waitHealth(port) {
  for (let i = 0; i < 100; i++) {
    try {
      const response = await fetch(`http://127.0.0.1:${port}/health`);
      if (response.ok) return;
    } catch {}
    await delay(20);
  }
  throw new Error("front door health timeout");
}

async function malformedConnection(port) {
  return new Promise((resolve, reject) => {
    const socket = connect(port, "127.0.0.1");
    let closed = false;
    let received = "";
    socket.setEncoding("utf8");
    socket.on("data", (chunk) => { received += chunk; });
    socket.on("error", () => {});
    socket.on("close", () => { closed = true; });
    socket.on("connect", async () => {
      socket.write("BROKEN REQUEST\r\n\r\n");
      await delay(500);
      const result = { closed, received_bytes: Buffer.byteLength(received) };
      if (!closed) socket.destroy();
      resolve(result);
    });
    socket.setTimeout(2000, () => reject(new Error("probe timeout")));
  });
}

let front;
let backend;
try {
  backend = createServer((request, response) => {
    if (request.url === "/health") {
      response.setHeader("content-type", "application/json");
      response.end(JSON.stringify({ status: "ok", name: "shell-mcp", role: "backend", backend_generation: "probe-1" }));
      return;
    }
    response.end("ok");
  });
  const backendPort = await listen(backend);
  const reserve = createServer();
  const frontPort = await listen(reserve);
  await new Promise((resolve) => reserve.close(resolve));
  const config = join(temp, "active.json");
  writeFileSync(config, `${JSON.stringify({ version: 1, port: backendPort, generation: "probe-1" })}\n`);
  front = spawn(process.execPath, [join(repo, "dist", "front-door.js")], {
    cwd: repo,
    env: {
      ...process.env,
      FRONT_DOOR_PORT: String(frontPort),
      MCP_BACKEND_CONFIG_PATH: config,
      MCP_PROCESS_ROUTE_PATH: join(temp, "routes.json"),
      FRONT_DOOR_REQUEST_LOG_PATH: join(temp, "requests.jsonl"),
    },
    stdio: ["ignore", "pipe", "pipe"],
    windowsHide: true,
  });
  await waitHealth(frontPort);
  const result = await malformedConnection(frontPort);
  console.log(JSON.stringify({ status: result.closed ? "PASS" : "FAIL", malformed_socket_closed_within_ms: result.closed, response_bytes: result.received_bytes, wait_ms: 500 }));
  assert.equal(result.closed, true, "front door retained a malformed client socket after clientError");
} finally {
  if (front?.exitCode === null) front.kill();
  if (backend?.listening) await new Promise((resolve) => backend.close(resolve));
  await delay(50);
  rmSync(temp, { recursive: true, force: true });
}

