$ErrorActionPreference='Stop'
$repo='C:\Users\Lauri\AppData\Local\ChatGPTMcpClean'
$keepalive=Join-Path $repo 'keepalive.ps1'
$rollbackArgs="-NoProfile -NonInteractive -WindowStyle Hidden -ExecutionPolicy Bypass -File `"$keepalive`" -Role Legacy -Port 3000 -PollSeconds 15"
$rollbackAction=New-ScheduledTaskAction -Execute 'powershell.exe' -Argument $rollbackArgs
foreach($taskName in @('ChatGPT Local Coder MCP','ShellMcpKeepAlive')) { Set-ScheduledTask -TaskName $taskName -Action $rollbackAction | Out-Null }
$supervisors=Get-CimInstance Win32_Process | Where-Object { $_.Name -eq 'powershell.exe' -and $_.CommandLine -match 'ChatGPTMcpClean\\keepalive\.ps1' }
$front=$supervisors | Where-Object { $_.CommandLine -match '-Role\s+FrontDoor' }
$all=$supervisors | Where-Object { $_.CommandLine -notmatch '-Role\s+(FrontDoor|Backend|Legacy)' }
if(@($front).Count -ne 1 -or @($all).Count -ne 1){ throw "Expected one FrontDoor and one All enforcement process; front=$(@($front).Count) all=$(@($all).Count)" }
$before=@{}
foreach($port in 3000,3002,3003){ $before[$port]=(Get-NetTCPConnection -LocalAddress 127.0.0.1 -LocalPort $port -State Listen).OwningProcess }
if($before[3000] -ne 21588 -or $before[3002] -ne 24468 -or $before[3003] -ne 14100){ throw "Listener ownership drifted before rollback: $($before | ConvertTo-Json -Compress)" }
Stop-Process -Id $front.ProcessId,$all.ProcessId -Force
Start-Sleep -Milliseconds 750
foreach($port in 3000,3002,3003){ $owner=(Get-NetTCPConnection -LocalAddress 127.0.0.1 -LocalPort $port -State Listen).OwningProcess; if($owner -ne $before[$port]){ throw "Listener $port changed during supervisor handoff: $($before[$port]) -> $owner" } }
Start-ScheduledTask -TaskName 'ChatGPT Local Coder MCP'
Start-Sleep -Seconds 2
$legacy=Get-CimInstance Win32_Process | Where-Object { $_.Name -eq 'powershell.exe' -and $_.CommandLine -match 'ChatGPTMcpClean\\keepalive\.ps1' -and $_.CommandLine -match '-Role\s+Legacy' }
if(@($legacy).Count -ne 1){ throw "Legacy supervisor did not establish exactly once; count=$(@($legacy).Count)" }
$ts='C:\Program Files\Tailscale\tailscale.exe'
& $ts funnel --yes --bg --https=443 'http://127.0.0.1:3000' | Out-Null
if($LASTEXITCODE -ne 0){ throw "Tailscale Funnel switch failed with exit $LASTEXITCODE" }
$failures=@()
$latencies=@()
for($i=0;$i -lt 80;$i++){
  $sw=[Diagnostics.Stopwatch]::StartNew()
  try { $h=Invoke-RestMethod 'https://kone.tailbf0440.ts.net/health' -TimeoutSec 3; if($h.status -ne 'ok' -or [int]$h.port -ne 3000 -or [int]$h.pid -ne 21588){ $failures += "sample=$i port=$($h.port) pid=$($h.pid)" } }
  catch { $failures += "sample=$i error=$($_.Exception.Message)" }
  $sw.Stop(); $latencies += $sw.Elapsed.TotalMilliseconds
  Start-Sleep -Milliseconds 125
}
Start-Sleep -Seconds 18
$status=& $ts funnel status --json | ConvertFrom-Json
$target=$status.Web.'kone.tailbf0440.ts.net:443'.Handlers.'/'.Proxy
if($target -ne 'http://127.0.0.1:3000'){ throw "Funnel target was rewritten after rollback: $target" }
foreach($port in 3000,3002,3003){ $owner=(Get-NetTCPConnection -LocalAddress 127.0.0.1 -LocalPort $port -State Listen).OwningProcess; if($owner -ne $before[$port]){ throw "Listener $port changed after rollback: $($before[$port]) -> $owner" } }
$wrong=Get-CimInstance Win32_Process | Where-Object { $_.Name -eq 'powershell.exe' -and $_.CommandLine -match 'ChatGPTMcpClean\\keepalive\.ps1' -and ($_.CommandLine -match '-Role\s+FrontDoor' -or $_.CommandLine -notmatch '-Role\s+(FrontDoor|Backend|Legacy)') }
if(@($wrong).Count -ne 0){ throw "3003 enforcement respawned: $(@($wrong | Select-Object ProcessId,CommandLine | ConvertTo-Json -Compress))" }
[pscustomobject]@{status=if($failures.Count -eq 0){'PASS'}else{'FAIL'};funnel_target=$target;public_samples=80;public_failures=$failures.Count;max_latency_ms=[math]::Round(($latencies | Measure-Object -Maximum).Maximum,2);legacy_supervisor_pid=$legacy.ProcessId;stopped_front_pid=$front.ProcessId;stopped_all_pid=$all.ProcessId;listener_3000=$before[3000];listener_3002=$before[3002];listener_3003=$before[3003]} | ConvertTo-Json -Compress
if($failures.Count){ $failures | Select-Object -First 10; exit 1 }

